#[rustler::nif]
pub fn build_editor_projection(document: Option<String>, options: EditorProjectionOptions) -> Result<EditorEnvelope, AlefNifError> {
    let document_core: Option<xberg::ExtractedDocument> = document
    .map(|s| serde_json::from_str::<xberg::ExtractedDocument>(&s))
    .transpose()
    .map_err(|error| format!("failed to deserialize parameter `document` for `build_editor_projection`: {error}"))?;
    Ok(hacienda::editor_projection::build_editor_projection(document_core.as_ref().unwrap_or(&Default::default()), &options.clone().into()).into())

}


