/// Reconcile regex and model detections into a single non-overlapping, offset-ordered list.
///
/// Two spans are treated as the same detection when their overlap ratio exceeds
/// `config.overlap_threshold`; the winner is chosen by `config.priority`.
#[rustler::nif]
pub fn merge_entities(regex_entities: Option<String>, model_entities: Option<String>, config: Option<String>) -> Result<Vec<MergedEntity>, AlefNifError> {
    let regex_entities_core_option: Option<Vec<hacienda::pii::RegexEntity>> = regex_entities
    .map(|s| serde_json::from_str::<Vec<hacienda::pii::RegexEntity>>(&s))
    .transpose()
    .map_err(|error| format!("failed to deserialize parameter `regex_entities` for `merge_entities`: {error}"))?;
    let regex_entities_core: Vec<hacienda::pii::RegexEntity> = regex_entities_core_option.unwrap_or_default();
    let model_entities_core_option: Option<Vec<hacienda::pii::ModelEntity>> = model_entities
    .map(|s| serde_json::from_str::<Vec<hacienda::pii::ModelEntity>>(&s))
    .transpose()
    .map_err(|error| format!("failed to deserialize parameter `model_entities` for `merge_entities`: {error}"))?;
    let model_entities_core: Vec<hacienda::pii::ModelEntity> = model_entities_core_option.unwrap_or_default();
    let config_core: Option<hacienda::pii::MergeConfig> = config
    .map(|s| serde_json::from_str::<hacienda::pii::MergeConfig>(&s))
    .transpose()
    .map_err(|error| format!("failed to deserialize parameter `config` for `merge_entities`: {error}"))?;
    Ok(hacienda::pii::merge_entities(regex_entities_core, model_entities_core, config_core.as_ref().unwrap_or(&Default::default())).into_iter().map(Into::into).collect())

}


