/// Open a durable audit store rooted at `root`, creating `root/{node_id}/` if it
/// does not exist yet.
///
/// Recovery — finding a tenant's existing segments, verifying their seal chain, and
/// replaying any unsealed segment left open by a previous run — no longer happens
/// here: it happens lazily, per tenant, the first time that tenant is touched (see
/// `ensure_tenant_loaded`). This method only creates
/// the node's root directory.
///
/// # Errors
///
/// `AuditError::Io` if directory creation fails.
#[rustler::nif]
pub fn fileauditstore_open(root: String, node_id: rustler::ResourceArc<NodeId>, config_hash: String) -> Result<ResourceArc<FileAuditStore>, AlefNifError> {
    let result = hacienda::audit::FileAuditStore::open(std::path::PathBuf::from(root), &node_id.inner.read().unwrap_or_else(|e| e.into_inner()).clone(), config_hash).map_err(alef_nif_err)?;
    Ok(ResourceArc::new(FileAuditStore { inner: Arc::new(std::sync::RwLock::new(result)) }))

}


/// Same as `open` but with an explicit sync policy.
#[rustler::nif]
pub fn fileauditstore_open_with_policy(root: String, node_id: rustler::ResourceArc<NodeId>, config_hash: String, sync_policy: SyncPolicy) -> Result<ResourceArc<FileAuditStore>, AlefNifError> {
    let result = hacienda::audit::FileAuditStore::open_with_policy(std::path::PathBuf::from(root), &node_id.inner.read().unwrap_or_else(|e| e.into_inner()).clone(), config_hash, sync_policy.into()).map_err(alef_nif_err)?;
    Ok(ResourceArc::new(FileAuditStore { inner: Arc::new(std::sync::RwLock::new(result)) }))

}


/// Builder: sets the sync policy after construction. Safe to call any time before a
/// tenant is first touched — recovery is lazy per tenant (see
/// `ensure_tenant_loaded`), so unlike before S1b this
/// is no longer racing against I/O `open` already performed.
/// `open_with_policy` remains the more direct way to set
/// the policy at construction time.
///
/// This method is provided for test ergonomics where the store is freshly created
/// and the caller wants to change the policy before appending anything.
#[rustler::nif]
pub fn fileauditstore_with_sync_policy(resource: rustler::ResourceArc<FileAuditStore>, policy: SyncPolicy) -> ResourceArc<FileAuditStore> {
    ResourceArc::new(FileAuditStore { inner: Arc::new(std::sync::RwLock::new(resource.inner.read().unwrap_or_else(|e| e.into_inner()).clone().with_sync_policy(policy.into()))) })
}


/// Builder: opt into recording how long `append` callers spend waiting to acquire
/// `io_order`, separate from the time spent minting and writing once acquired.
///
/// Off by default: measuring costs a pair of `Instant::now()` calls per `append`,
/// which this crate does not pay unless something is actually asking for the
/// number. See the phase2 plan's Task 5, Design Decision D2.
#[rustler::nif]
pub fn fileauditstore_with_contention_tracking(resource: rustler::ResourceArc<FileAuditStore>) -> ResourceArc<FileAuditStore> {
    ResourceArc::new(FileAuditStore { inner: Arc::new(std::sync::RwLock::new(resource.inner.read().unwrap_or_else(|e| e.into_inner()).clone().with_contention_tracking())) })
}


#[rustler::nif(schedule = "DirtyCpu")]
#[allow(clippy::await_holding_lock)]
pub fn fileauditstore_append_async(resource: rustler::ResourceArc<FileAuditStore>, tenant: rustler::ResourceArc<TenantId>, inputs: Option<String>) -> Result<Vec<AuditEntry>, AlefNifError> {
    let inputs_core_option: Option<Vec<hacienda::audit::AuditEntryInput>> = inputs
    .map(|s| serde_json::from_str::<Vec<hacienda::audit::AuditEntryInput>>(&s))
    .transpose()
    .map_err(|error| format!("failed to deserialize parameter `inputs` for `fileauditstore_append_async`: {error}"))?;
    let inputs_core: Vec<hacienda::audit::AuditEntryInput> = inputs_core_option.unwrap_or_default();
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        std::thread::Builder::new()
            .stack_size(32 * 1024 * 1024)
            .spawn(move || {
                // 16 MiB: the spawning thread's 32 MiB only covers `block_on`; tasks the
                // future spawns run on tokio workers, whose ~2 MB default stack can overflow on
                // a deep extraction future (a nested archive member, a multi-stage OCR
                // pipeline), aborting the process with SIGBUS rather than raising a panic.
                const NIF_RUNTIME_STACK_SIZE_BYTES: usize = 16 * 1024 * 1024;
                let rt = tokio::runtime::Builder::new_multi_thread()
                    .enable_all()
                    .thread_stack_size(NIF_RUNTIME_STACK_SIZE_BYTES)
                    .build()
                    .map_err(|e| e.to_string())?;
                let result = rt.block_on(async { resource.inner.read().unwrap_or_else(|e| e.into_inner()).append(&tenant.inner.read().unwrap_or_else(|e| e.into_inner()).clone(), inputs_core).await }).map_err(alef_nif_err)?;
                Ok::<_, AlefNifError>(result.into_iter().map(Into::into).collect())
            })
            .map_err(|e| e.to_string())?
            .join()
            .map_err(|_| "thread panicked".to_string())
    }));
    match result {
        Ok(inner_result) => inner_result?,
        Err(_) => Err(AlefNifError::from("thread panic during async operation".to_string())),
    }

}


