/// Drop entities the backend scores below `threshold`.
///
/// Entities without a confidence score are kept: a backend that does not report
/// confidence should not be silently filtered to nothing.
///
/// # Candle GLiNER threshold floor
///
/// `xberg::text::ner::candle::CandleBackend::detect` hard-codes an internal
/// threshold of `0.5` before `NerDetector`'s own filter runs. Consequently
/// `with_threshold` can only ever *raise* the effective threshold above `0.5`;
/// it can never lower it. Entities the Candle backend scores below `0.5` are
/// invisible at any configured threshold, so every recall figure measured
/// through this detector is *truncated recall at 0.5*, not recall. This is an
/// upstream xberg limitation, not something this crate can work around without
/// patching `CandleBackend::detect`.
#[rustler::nif]
pub fn nerdetector_with_threshold(resource: rustler::ResourceArc<NerDetector>, threshold: f32) -> ResourceArc<NerDetector> {
    ResourceArc::new(NerDetector { inner: Arc::new(std::sync::RwLock::new(resource.inner.read().unwrap_or_else(|e| e.into_inner()).clone().with_threshold(threshold))) })
}


#[cfg(all (feature = "ner-candle" , not (target_arch = "wasm32")))]
/// Load the Candle GLiNER2 backend from a local model directory, optionally
/// merging a LoRA adapter.
///
/// Backends are cached process-wide by `(model_dir, lora_adapter_dir)`, so the
/// model-load and adapter-merge cost is paid once per pair rather than per document.
///
/// When `expected_weights_hash` is `Some`, the blake3 digest is checked against
/// the exact bytes handed to Candle, and the backend is built from those same
/// bytes via the uncached in-memory loader. A mismatch aborts with
/// `PiiError::Ner` so a tampered or corrupted model can never be executed.
/// That path intentionally rejects a LoRA adapter: merged adapter bytes cannot
/// be bound to the base-weights digest, so verification must fail closed.
///
/// Without a hash, the resulting detector reports `runtime_ready = true` with
/// no model id: a privately fine-tuned/unpinned model is still model-backed
/// even though there is no registry identity to report.
///
/// # Errors
///
/// Returns `PiiError::Ner` if the model or adapter cannot be loaded, or if
/// `expected_weights_hash` is set and the weights digest does not match.
#[rustler::nif]
pub fn nerdetector_from_candle_local(model_dir: String, lora_adapter_dir: Option<String>, expected_weights_hash: Option<String>) -> Result<ResourceArc<NerDetector>, AlefNifError> {
    let result = hacienda::pii::NerDetector::from_candle_local(&std::path::PathBuf::from(model_dir), &std::path::PathBuf::from(lora_adapter_dir), expected_weights_hash.as_deref()).map_err(alef_nif_err)?;
    Ok(ResourceArc::new(NerDetector { inner: Arc::new(std::sync::RwLock::new(result)) }))

}


#[cfg(all (feature = "ner-candle" , not (target_arch = "wasm32")))]
/// Load a pinned GLiNER2 model, verifying the local directory against the
/// shared registry before any bytes reach Candle.
///
/// The host still owns download and caching; this guard only enforces the
/// integrity contract at the seam. Unpinned/private models should use
/// `from_candle_local` directly.
///
/// The load deliberately bypasses xberg's path-keyed backend cache: that cache
/// can hold a backend built from earlier bytes at the same directory, so reusing
/// it after verification would verify one set of weights and run another. A
/// verified load always builds a fresh backend from the directory just verified,
/// never from that cache.
#[rustler::nif]
pub fn nerdetector_from_candle_local_verified(model_dir: String, lora_adapter_dir: Option<String>, model_id: String) -> Result<ResourceArc<NerDetector>, AlefNifError> {
    let result = hacienda::pii::NerDetector::from_candle_local_verified(&std::path::PathBuf::from(model_dir), &std::path::PathBuf::from(lora_adapter_dir), &model_id).map_err(alef_nif_err)?;
    Ok(ResourceArc::new(NerDetector { inner: Arc::new(std::sync::RwLock::new(result)) }))

}


#[cfg(all (target_arch = "wasm32" , feature = "ner-candle-wasm"))]
/// `from_candle_local`'s wasm32 sibling: loads the same
/// Candle GLiNER2 backend from in-memory bytes rather than a filesystem model
/// directory — a browser has no disk to read `model_dir` from. The caller (Studio)
/// already fetches and IndexedDB-caches these three buffers for its own NER pass;
/// this does not fetch anything itself.
