pub fn regexengine_find_all(resource: rustler::ResourceArc<RegexEngine>, text: String) -> Vec<RegexEntity> {
    resource.inner.read().unwrap_or_else(|e| e.into_inner()).find_all(&text).into_iter().map(Into::into).collect()
}


