#[rustler::nif]
pub fn segment_id(resource: rustler::ResourceArc<Segment>) -> String {
    resource.inner.read().unwrap_or_else(|e| e.into_inner()).id().into()
}


/// The node that owns this segment.
#[rustler::nif]
pub fn segment_node_id(resource: rustler::ResourceArc<Segment>) -> ResourceArc<NodeId> {
    ResourceArc::new(NodeId { inner: Arc::new(std::sync::RwLock::new(resource.inner.read().unwrap_or_else(|e| e.into_inner()).node_id().clone())) })
}


/// The tenant this segment belongs to.
#[rustler::nif]
pub fn segment_tenant_id(resource: rustler::ResourceArc<Segment>) -> ResourceArc<TenantId> {
    ResourceArc::new(TenantId { inner: Arc::new(std::sync::RwLock::new(resource.inner.read().unwrap_or_else(|e| e.into_inner()).tenant_id().clone())) })
}


/// Chain hash of the most recent entry, or `GENESIS_HASH` when empty.
#[rustler::nif]
pub fn segment_tip(resource: rustler::ResourceArc<Segment>) -> String {
    resource.inner.read().unwrap_or_else(|e| e.into_inner()).tip().into()
}


/// Number of entries pushed so far.
#[rustler::nif]
pub fn segment_len(resource: rustler::ResourceArc<Segment>) -> usize {
    resource.inner.read().unwrap_or_else(|e| e.into_inner()).len()
}


/// `true` when no entries have been pushed.
#[rustler::nif]
pub fn segment_is_empty(resource: rustler::ResourceArc<Segment>) -> bool {
    resource.inner.read().unwrap_or_else(|e| e.into_inner()).is_empty()
}


/// All entries in this segment, in push order.
#[rustler::nif]
pub fn segment_entries(resource: rustler::ResourceArc<Segment>) -> Vec<AuditEntry> {
    resource.inner.read().unwrap_or_else(|e| e.into_inner()).entries().iter().cloned().map(Into::into).collect()
}


/// Append a pre-minted entry read back from storage, rejecting it if it does not extend
/// this segment's chain.
///
/// This is the recovery counterpart to `push`: `push` mints a new entry,
/// this validates one that already exists on disk. Delegating to
/// `AuditChain::append` means a replayed file that was edited on disk fails at load
/// time rather than being silently adopted into a live chain — which is the property
/// that makes `FileAuditStore::open` fail on a tampered `.jsonl`.
///
/// # Errors
///
/// - `AuditError::ConfigMismatch` — the entry was minted under a different config.
/// - `AuditError::ChainIntegrity` — the entry's chain hash does not follow the tip.
#[rustler::nif]
pub fn segment_append(resource: rustler::ResourceArc<Segment>, entry: AuditEntry) -> Result<(), AlefNifError> {
    let result = resource.inner.write().unwrap_or_else(|e| e.into_inner()).append(entry.into()).map_err(alef_nif_err)?;
    Ok(result)

}


/// Verify the internal entry chain — delegates to `AuditChain::verify`, unchanged.
///
/// This confirms that no entry within this segment was tampered with. It says nothing
/// about the link to adjacent segments; use `verify_seal_chain` for that.
#[rustler::nif]
pub fn segment_verify(resource: rustler::ResourceArc<Segment>) -> Result<(), AlefNifError> {
    let result = resource.inner.read().unwrap_or_else(|e| e.into_inner()).verify().map_err(alef_nif_err)?;
    Ok(result)

}


/// Attach a project. Does not change what this context is authorized to reach —
/// only `tenant` does that (D-S1-2).
#[rustler::nif]
pub fn tenantctx_with_project(obj: TenantCtx, project: rustler::ResourceArc<ProjectId>) -> TenantCtx {
    hacienda::TenantCtx::from(obj).with_project(&project.inner.read().unwrap_or_else(|e| e.into_inner()).clone()).into()
}


/// The context every pre-S1 row is migrated onto (spec §8). Also the context an
/// in-process `Trusted` caller acts under today, since a
/// trusted caller has no tenant of its own to assert — see
/// `Caller::tenant_ctx`'s doc comment for the open question this leaves for
/// deployments that want a trusted caller scoped to a specific tenant.
#[rustler::nif]
pub fn tenantctx_default_tenant(actor: rustler::ResourceArc<ActorId>) -> TenantCtx {
    hacienda::TenantCtx::default_tenant(&actor.inner.read().unwrap_or_else(|e| e.into_inner()).clone()).into()
}


/// Wrap an existing identifier (e.g. one read back from a store row).
#[rustler::nif]
pub fn tenantid_new(id: String) -> ResourceArc<TenantId> {
    ResourceArc::new(TenantId { inner: Arc::new(std::sync::RwLock::new(hacienda::TenantId::new(id))) })
}


/// The identifier for the single tenant that owns every row created before S1 shipped
/// (spec §8's migration path). There is, by construction, only ever one deployment
/// migrating into this identifier — an existing single-tenant install.
#[rustler::nif]
pub fn tenantid_default_tenant() -> ResourceArc<TenantId> {
    ResourceArc::new(TenantId { inner: Arc::new(std::sync::RwLock::new(hacienda::TenantId::default_tenant())) })
}


/// The underlying identifier string.
#[rustler::nif]
pub fn tenantid_as_str(resource: rustler::ResourceArc<TenantId>) -> String {
    resource.inner.read().unwrap_or_else(|e| e.into_inner()).as_str().into()
}


#[rustler::nif]
pub fn tenantpseudonymiserregistry_new() -> ResourceArc<TenantPseudonymiserRegistry> {
    ResourceArc::new(TenantPseudonymiserRegistry { inner: Arc::new(std::sync::RwLock::new(hacienda::redaction::pseudonym::TenantPseudonymiserRegistry::new())) })
}


/// Resolve and cache `tenant`'s pseudonymiser.
///
/// Idempotent, and safe to call again for an already-admitted tenant — the existing
/// entry is replaced with a freshly resolved one. That is the path a key rotation
/// takes (see P3): re-admit the tenant after the resolver reports a new active key.
///
/// # Errors
///
/// Whatever `resolver` returns for a missing or malformed key — see
/// `Pseudonymiser::new` / `Pseudonymiser::with_active`.
#[rustler::nif]
pub fn tenantpseudonymiserregistry_admit(resource: rustler::ResourceArc<TenantPseudonymiserRegistry>, tenant: rustler::ResourceArc<TenantId>, resolver: rustler::ResourceArc<KeyResolver>, active: rustler::ResourceArc<KeyId>, retired: Vec<KeyId>) -> Result<(), AlefNifError> {
    let result = resource.inner.read().unwrap_or_else(|e| e.into_inner()).admit(&tenant.inner.read().unwrap_or_else(|e| e.into_inner()).clone(), &resolver.inner.read().unwrap_or_else(|e| e.into_inner()).clone(), &active.inner.read().unwrap_or_else(|e| e.into_inner()).clone(), &retired).map_err(alef_nif_err)?;
    Ok(result)

}


/// The admitted pseudonymiser for `tenant`, if any.
///
/// `None` means the tenant was never admitted (or its last admission attempt
/// failed and nothing was cached) — a caller must treat this the same as
/// "pseudonymization is not configured for this tenant", never invent a key.
#[rustler::nif]
pub fn tenantpseudonymiserregistry_get(resource: rustler::ResourceArc<TenantPseudonymiserRegistry>, tenant: rustler::ResourceArc<TenantId>) -> Option<ResourceArc<Pseudonymiser>> {
    resource.inner.read().unwrap_or_else(|e| e.into_inner()).get(&tenant.inner.read().unwrap_or_else(|e| e.into_inner()).clone()).map(|v| ResourceArc::new(Pseudonymiser { inner: Arc::new(std::sync::RwLock::new(v)) }))
}


/// Whether `tenant` has been admitted.
#[rustler::nif]
pub fn tenantpseudonymiserregistry_contains(resource: rustler::ResourceArc<TenantPseudonymiserRegistry>, tenant: rustler::ResourceArc<TenantId>) -> bool {
    resource.inner.read().unwrap_or_else(|e| e.into_inner()).contains(&tenant.inner.read().unwrap_or_else(|e| e.into_inner()).clone())
}


/// A built-in vertical requesting every `PiiCategory` the taxonomy
/// defines, beyond the five categories every pipeline already requests by default.
/// Strictly opt-in: nothing constructs this except a caller that asks for it by
/// name (e.g. `--vertical comprehensive` on the CLI) — `PipelineConfig::default`
/// still leaves `vertical` at `None`. See `COMPREHENSIVE_LABELS` for what's
/// excluded and why.
#[rustler::nif]
pub fn verticalconfig_comprehensive() -> VerticalConfig {
    hacienda::pii::VerticalConfig::comprehensive().into()
}


/// Validate this vertical's shape.
///
/// Checks, independent of redaction mode and of whether a model is actually
/// loaded: `id` is non-empty, has no leading/trailing whitespace, and does not
/// contain `@` (reserved as `Self::provenance_id`'s separator); `labels` is
/// non-empty; every label is non-empty after trimming and has no leading/trailing
/// whitespace of its own (an untrimmed label would otherwise pass this check but
/// flow untrimmed into detection and `provenance_id`'s hash input); no label
/// contains `[`, `:`, or `]` (mirroring
/// `category_label`, since a vertical label that
/// cannot be pseudonymised is a configuration error regardless of the configured
/// redaction mode); no label case-insensitively duplicates a base NER category
/// name (`person`, `organization`, `location`, `email`, `phone` — already
/// requested by default, see `DEFAULT_CATEGORIES`); and no two
/// labels are equal after case-folding.
///
/// # Errors
///
/// Returns `PiiError::InvalidVertical` naming this vertical's `id` and the first
/// reason it failed.
#[rustler::nif]
pub fn verticalconfig_validate(obj: String) -> Result<(), AlefNifError> {
    let obj: hacienda::pii::VerticalConfig = serde_json::from_str::<hacienda::pii::VerticalConfig>(&obj)
    .map_err(|error| format!("failed to deserialize parameter `obj` for `verticalconfig_validate`: {error}"))?;
    let result = obj.validate().map_err(alef_nif_err)?;
    Ok(result)

}


/// The value recorded in the audit chain for detections this vertical produced.
///
/// `"<id>@<first 8 hex of blake3 over the sorted, case-folded label set>"`, e.g.
/// `finance@3f9a1c02`. An id alone would be a false provenance claim: the same id
/// with a different label set detects different things, and the audit record's job
/// is to say what *was* detectable at the time. Sorting and case-folding the labels
/// before hashing makes the digest stable under reordering or a stray case change
/// in config, while still changing whenever the actual label *set* changes — see
/// `AuditEntry::vertical`.
#[rustler::nif]
pub fn verticalconfig_provenance_id(obj: VerticalConfig) -> String {
    hacienda::pii::VerticalConfig::from(obj).provenance_id()
}


