    env.register::<DpiaGenerator>().expect("Failed to register resource type DpiaGenerator");
    env.register::<EntityGlossary>().expect("Failed to register resource type EntityGlossary");
    env.register::<EnvKeyResolver>().expect("Failed to register resource type EnvKeyResolver");
    env.register::<FileAuditStore>().expect("Failed to register resource type FileAuditStore");
    env.register::<FileReviewStore>().expect("Failed to register resource type FileReviewStore");
    env.register::<FileSink>().expect("Failed to register resource type FileSink");
    env.register::<HaciendaFacade>().expect("Failed to register resource type HaciendaFacade");
    env.register::<InMemoryAuditStore>().expect("Failed to register resource type InMemoryAuditStore");
    env.register::<InMemoryDocumentDossierIndex>().expect("Failed to register resource type InMemoryDocumentDossierIndex");
    env.register::<InMemoryDossierAcl>().expect("Failed to register resource type InMemoryDossierAcl");
    env.register::<InMemoryJobStore>().expect("Failed to register resource type InMemoryJobStore");
    env.register::<InMemoryReviewStore>().expect("Failed to register resource type InMemoryReviewStore");
    env.register::<IndexedDbAuditStore>().expect("Failed to register resource type IndexedDbAuditStore");
    env.register::<KeyId>().expect("Failed to register resource type KeyId");
    env.register::<NerDetector>().expect("Failed to register resource type NerDetector");
    env.register::<NodeId>().expect("Failed to register resource type NodeId");
    env.register::<PiiPipeline>().expect("Failed to register resource type PiiPipeline");
    env.register::<ProjectId>().expect("Failed to register resource type ProjectId");
    env.register::<PseudonymKey>().expect("Failed to register resource type PseudonymKey");
    env.register::<Pseudonymiser>().expect("Failed to register resource type Pseudonymiser");
    env.register::<RedactionEngine>().expect("Failed to register resource type RedactionEngine");
    env.register::<RegexEngine>().expect("Failed to register resource type RegexEngine");
    env.register::<ReviewQueue>().expect("Failed to register resource type ReviewQueue");
    env.register::<Segment>().expect("Failed to register resource type Segment");
    env.register::<TenantId>().expect("Failed to register resource type TenantId");
